import pathlib,subprocess,os,time,json,statistics,sys
root=pathlib.Path('/tmp/stash-rss-4755');source=root/'repo'
def git(p,*args,input=None):
 c=subprocess.run(['git',*args],cwd=p,input=input,stdout=subprocess.PIPE,stderr=subprocess.PIPE,check=True)
 return c.stdout

def setup(n):
 p=source if n==120000 else root/f'repo-{n}'
 if not p.exists():
  p.mkdir();git(p,'init','-q','-b','main')
  for k,v in [('user.name','Mono Dev'),('user.email','mono@example.com'),('gc.auto','0')]:git(p,'config',k,v)
  (p/'.git/objects/info/alternates').write_text(str(source/'.git/objects')+'\n')
  tree=git(source,'ls-tree','HEAD').splitlines(keepends=True)[:n//300]
  oid=git(p,'mktree',input=b''.join(tree)).strip().decode()
  commit=git(p,'commit-tree',oid,input=b'wide base\n').strip().decode()
  git(p,'update-ref','refs/heads/main',commit);git(p,'reset','--hard','-q','HEAD')
 if not (p/'.git/refs/grit-bench/stash-memory').exists():
  git(p,'reset','--hard','-q','HEAD')
  for path in git(p,'ls-files').decode().splitlines()[:3000]:
   with (p/path).open('a') as f:f.write('stash repeat\n')
  oid=git(p,'stash','create','repeat').strip().decode()
  git(p,'update-ref','refs/grit-bench/stash-memory',oid);git(p,'reset','--hard','-q','HEAD')
 return p

if sys.argv[1]=='setup':
 for n in [30000,60000,120000]:print(n,setup(n),flush=True)
 quit()
# PROFILE=release|dist PHASE=before|after. Once fixed, run all three tools interleaved.
phase=os.environ['PHASE'];profile=os.environ['PROFILE']
tools={'git':['git','stash','pop'] ,'main':[f'/tmp/grit-main-{profile}','stash','pop']}
if phase=='after':tools['fixed']=[f'/tmp/grit-fixed-{profile}','stash','pop']
results=[]
for n in map(int, os.environ.get("SIZES", "30000,60000,120000").split(",")):
 p=setup(n);oid=git(p,'rev-parse','refs/grit-bench/stash-memory').strip().decode()
 for flags in [[],['--json'],['--markdown']]:
  if os.environ.get('ONLY_HUMAN') and flags:continue
  expected=None
  for round in range(4):
   order=list(tools)
   if round%2:order.reverse()
   for name in order:
    git(p,'reset','--hard','-q','HEAD');git(p,'stash','clear');git(p,'stash','store','-m','repeat',oid)
    cmd=tools[name]+([] if name=='git' else flags)
    report=root/'time-scale.txt';start=time.perf_counter()
    subprocess.run(['/usr/bin/time','-v','-o',str(report),*cmd],cwd=p,stdout=subprocess.DEVNULL,stderr=subprocess.PIPE,check=True)
    ms=(time.perf_counter()-start)*1000
    raw=report.read_text();rss=int(next(l for l in raw.splitlines() if 'Maximum resident' in l).split(':')[1])
    state=[git(p,*args) for args in [('diff','--binary'),('diff','--cached','--binary'),('ls-files','--stage'),('status','--porcelain')]]
    assert not git(p,'stash','list')
    if expected is None:expected=state
    else:assert state==expected,(n,flags,name)
    if round:
     row={'files':n,'edits':3000,'profile':profile,'format':flags[0] if flags else 'human','tool':name,'round':round,'wall_ms':float(f'{ms:.2f}'),'rss_kib':rss,'time_v':raw}
     results.append(row);print(json.dumps({k:v for k,v in row.items() if k!='time_v'}),flush=True)
 git(p,'fsck','--strict')
(root/f'{phase}-{profile}-scale{os.environ.get("SUFFIX","")}.json').write_text(json.dumps(results,indent=2))

